Definition supp_ok (b : expr) (off n : Z) : bool :=
  (0 <=? n) &&
  match b with
  | ELit z => (z =? 0) && (0 <=? off) && (off + n <=? 7094272)
  | EVar v => if Nat.eqb v 2 then (-4864 <=? off) && (off + n <=? 16)
              else if Nat.eqb v 53 then (0 <=? off) && (off + n <=? 512) && ((off + n <=? 32) || (287 <=? off))
              else if Nat.eqb v 11 then (0 <=? off) && (off + n <=? 8)
              else if Nat.eqb v 32 then (0 <=? off) && (off + n <=? 24)
              else false
  | _ => match srl3_of b with
         | Some v => if Nat.eqb v 11 then (SBz <=? off) && (off + n <=? SBz + 1)
                     else if Nat.eqb v 53 then (SBz <=? off) && (off + n <=? SBz + 64) else false
         | None => false
         end
  end.
(* [comment removed for export] *)
Definition def_ok (b : expr) (off n : Z) : bool :=
  (0 <=? n) &&
  match b with
  | EVar v => if Nat.eqb v 2 then (-4864 <=? off) && (off + n <=? 16)
              else if (Nat.eqb v 53 || Nat.eqb v 48 || Nat.eqb v 11 || Nat.eqb v 32)%bool then (0 <=? off) else false
  | _ => match srl3_of b with
         | Some v => Nat.eqb v 53 && (SBz <=? off)
         | None => false
         end
  end.
