  (7094272 <= s2 /\ s2 + 24 <= 2 ^ 47 /\ (F + 512 <= s2 \/ s2 + 24 <= F)) /\
  7094272 <= fl.
Ltac bsplit H := repeat (lazymatch type of H with
  | (_ && _)%bool = true => let H1 := fresh "Hb" in apply andb_prop in H as [H H1]
